def calculate_max_speed(speeds_and_distances: List[Tuple[float, float]],
    extreemes_percentile: float, ignore_nonstandard_distances: bool
    ) ->Optional[float]:
    if not speeds_and_distances:
        return None

    # Filter out None/zero speeds
    valid = [(speed, dist) for speed, dist in speeds_and_distances if speed is not None and speed > 0]

    if not valid:
        return None

    if extreemes_percentile == 0 and not ignore_nonstandard_distances:
        # Raw max speed
        return max(speed for speed, dist in valid)

    speeds = [speed for speed, dist in valid]
    distances = [dist for speed, dist in valid]

    if ignore_nonstandard_distances and len(distances) > 0:
        mean_distance = sum(distances) / len(distances)
        if mean_distance > 0:
            filtered = [(speed, dist) for speed, dist in valid
                       if dist <= mean_distance * 1.5 or not ignore_nonstandard_distances]
            if filtered:
                valid = filtered

    if not valid:
        return None

    speeds = sorted([speed for speed, dist in valid])

    if extreemes_percentile > 0 and len(speeds) > 1:
        # Remove top extreemes_percentile% of speeds
        n = len(speeds)
        cutoff_index = int(n * (1 - extreemes_percentile / 100.0))
        if cutoff_index < 1:
            cutoff_index = 1
        speeds = speeds[:cutoff_index]

    if not speeds:
        return None

    return max(speeds)
